@use '@smart/web-components/dist/scss/variables' as *;

.discountPricing {
  &__label-wrapper {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: baseline;
    margin-right: var(--spacing-300);

    @include breakpoint(l) {
      margin-right: var(--spacing-500);
    }
  }

  &__label {
    color: var(--c-mid-contrast);
    margin-right: var(--spacing-50);
  }

  &__price-wrapper {
    display: flex;
    flex-direction: row;
    align-items: flex-end;
    gap: var(--spacing-50);
  }

  &__price-discounted {
    color: var(--sig-error);
  }

  &__base-price-wrapper {
    display: flex;
    flex-direction: row;
    align-items: flex-start;
    gap: var(--spacing-50);
    flex-wrap: wrap;
  }

  &__base-price-content {
    flex: 1;
    min-width: 0;
    max-width: 126px;
    letter-spacing: -0.04em;

    @include breakpoint(l) {
      max-width: 156px;
    }
  }

  &__base-price {
    display: inline;
    text-decoration: line-through;
    text-decoration-color: var(--sig-error);
    font-size: calc(var(--font-size-lgl-100) + 1px);
  }

  &__base-price-label {
    display: inline;
    font-size: calc(var(--font-size-lgl-100) + 1px);
    word-break: break-word;
  }

  &__discount-badge {
    display: inline-flex;
    height: 20px;
    padding: 4px var(--Spacing_100, 8px) 4px var(--Spacing_100, 8px);
    align-items: center;
    gap: var(--spacing-50);
    border-radius: var(--Spacing_100, 8px);
    background-color: var(--sig-error);
    color: white;
    font-size: var(--font-size-lgl-100);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    vertical-align: middle;
  }

  &__description {
    color: var(--c-mid-contrast);
  }
}

